Literal.Value:
'{
  "data": {
    "name": "dataset"
  },
  "width": "container",
  "height": "container",
  "transform": [
    {
      "filter": "isValid(datum[''Não realizada (GWh)''])"
    },
    {
      "calculate": "month(datum[''Mês''])",
      "as": "m"
    },
    {
      "calculate": "[''jan'',''fev'',''mar'',''abr'',''mai'',''jun'',''jul'',''ago'',''set'',''out'',''nov'',''dez''][datum.m]",
      "as": "mes"
    },
    {
      "calculate": "year(datum[''Mês''])",
      "as": "ano"
    },
    {
      "calculate": "datum[''Não realizada (GWh)''] / (datum[''Geração (GWh)''] + datum[''Não realizada (GWh)''])",
      "as": "pct"
    }
  ],
  "encoding": {
    "x": {
      "field": "mes",
      "type": "ordinal",
      "sort": {
        "field": "m"
      },
      "title": null,
      "axis": {
        "labelAngle": 0,
        "orient": "top",
        "ticks": false
      }
    },
    "y": {
      "field": "ano",
      "type": "ordinal",
      "title": null,
      "axis": {
        "ticks": false
      }
    }
  },
  "layer": [
    {
      "mark": {
        "type": "rect",
        "stroke": "#FFFFFF",
        "strokeWidth": 2
      },
      "encoding": {
        "color": {
          "field": "Não realizada (GWh)",
          "type": "quantitative",
          "scale": {
            "type": "sqrt",
            "range": [
              "#FDF8DC",
              "#F2C811",
              "#967100",
              "#191919"
            ]
          },
          "legend": {
            "orient": "bottom",
            "title": "GWh",
            "gradientLength": 160,
            "format": ",.0f"
          }
        },
        "tooltip": [
          {
            "field": "mes",
            "title": "Mês"
          },
          {
            "field": "ano",
            "title": "Ano"
          },
          {
            "field": "Não realizada (GWh)",
            "title": "Não realizada (GWh)",
            "format": ",.0f"
          },
          {
            "field": "pct",
            "title": "% cortado",
            "format": ".1%"
          }
        ],
        "opacity": {
          "condition": {
            "test": "datum.__selected__ == ''off''",
            "value": 0.25
          },
          "value": 1
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "fontSize": 9
      },
      "encoding": {
        "text": {
          "field": "Não realizada (GWh)",
          "format": ",.0f"
        },
        "color": {
          "condition": {
            "test": "datum[''Não realizada (GWh)''] > 1500",
            "value": "#FFFFFF"
          },
          "value": "#191919"
        },
        "opacity": {
          "condition": {
            "test": "datum.__selected__ == ''off''",
            "value": 0.25
          },
          "value": 1
        }
      }
    }
  ]
}'
